import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns CSV string with header', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv ends with newline', () => {
  const result = exportCsv([]);
  assert(result.endsWith('\n'));
});

test('exportCsv with single invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[1].includes('Alice'));
});

test('exportCsv includes all required columns', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const row = lines[1];

  assert(row.includes('INV-2026-0001'));
  assert(row.includes('Alice'));
  assert(row.includes('2026-10-07'));
  assert(row.includes('2026-11-06'));
  assert(row.includes('issued'));
});

test('exportCsv formats amounts with 2 decimals', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const row = lines[1];

  const matches = row.match(/\d+\.\d{2}/g);
  assert(matches && matches.length > 0);
  matches.forEach(match => {
    assert.equal(match.split('.')[1].length, 2);
  });
});

test('exportCsv uses dot decimal separator', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const row = lines[1];

  const hasCommaDecimals = /\d+,\d{2}/.test(row);
  assert.equal(hasCommaDecimals, false);
});

test('exportCsv includes customer name from lookup', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const row = lines[1];

  assert(row.includes('Bob'));
});

test('exportCsv escapes fields with commas', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');

  assert(result.includes('Alice'));
});

test('exportCsv escapes fields with quotes', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);

  assert(result.includes('Carol'));
});

test('exportCsv with multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, []);
  assert.equal(issued2.ok, true);

  const result = exportCsv([issued1.value, issued2.value]);
  const lines = result.split('\n');

  assert.equal(lines.length, 4);
  assert(lines[1].includes('Bob'));
  assert(lines[2].includes('Alice'));
});

test('exportCsv calculates correct totals', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const totals = invoiceTotals(issued.value);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const row = lines[1];

  const expected = `${(totals.subtotal / 100).toFixed(2)},${(totals.discount / 100).toFixed(2)},${(totals.vat / 100).toFixed(2)},${(totals.total / 100).toFixed(2)}`;
  assert(row.includes(expected.split(',')[0]));
});

test('exportCsv with partial payment', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issued.value, { amount: 20000, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const result = exportCsv([paid.value]);
  const lines = result.split('\n');
  const row = lines[1];

  assert(row.includes('partially_paid'));
});

test('exportCsv with paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const result = exportCsv([paid.value]);
  const lines = result.split('\n');
  const row = lines[1];

  assert(row.includes('paid'));
  assert(row.endsWith('0.00'));
});

test('exportCsv with draft invoice', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(draft.ok, true);

  const result = exportCsv([draft.value]);
  const lines = result.split('\n');

  assert.equal(lines.length, 3);
  assert(lines[1].includes('draft'));
});

test('exportCsv with discounted line', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const totals = invoiceTotals(issued.value);
  assert(totals.discount > 0);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const row = lines[1];

  assert(row.includes('0.00') === false || totals.discount > 0);
});

test('exportCsv with multiple lines', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');

  assert.equal(lines.length, 3);
});

test('exportCsv preserves invoice order', () => {
  const invoices = [];

  for (let i = 0; i < 3; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: `2026-10-${String(7 + i).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 5 + i }],
    });
    assert.equal(inv.ok, true);
    const issued = issueInvoice(inv.value, []);
    assert.equal(issued.ok, true);
    invoices.push(issued.value);
  }

  const result = exportCsv(invoices);
  const lines = result.split('\n');

  assert.equal(lines.length, 5);
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[2].includes('INV-2026-0002'));
  assert(lines[3].includes('INV-2026-0003'));
});

test('exportCsv handles empty invoice list', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');

  assert.equal(lines.length, 2);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], '');
});

test('exportCsv with voucher', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');

  assert.equal(lines.length, 3);
  assert(lines[1].includes('85000'));
});

test('exportCsv with VAT and discount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
    ],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const totals = invoiceTotals(issued.value);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const row = lines[1];

  assert(row.includes('issued'));
  assert(totals.discount > 0);
  assert(totals.vat > 0);
});

test('exportCsv amounts are plain euros', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);

  assert(!result.includes('€'));
  assert(!result.includes(' '));
});

test('exportCsv CSV is parseable', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n').filter(line => line.length > 0);

  assert.equal(lines.length, 2);

  const headers = lines[0].split(',');
  assert.equal(headers.length, 10);
  assert.equal(headers[0], 'number');
  assert.equal(headers[1], 'customer');
});

